func TestIsPkgCvesDetactable(t *testing.T) {
	base := models.ScanResult{
		Family: "debian", Release: "12", Packages: models.Packages{"apt": {Name: "apt"}},
	}
	tests := []struct {
		name string
		edit func(*models.ScanResult)
		want bool
	}{
		{"supported", func(*models.ScanResult) {}, true},
		{"missing family", func(r *models.ScanResult) { r.Family = "" }, false},
		{"missing version", func(r *models.ScanResult) { r.Release = "" }, false},
		{"no packages", func(r *models.ScanResult) { r.Packages = nil }, false},
		{"Trivy", func(r *models.ScanResult) { r.ScannedBy = "trivy" }, false},
		{"FreeBSD", func(r *models.ScanResult) { r.Family = constant.FreeBSD }, false},
		{"Raspbian", func(r *models.ScanResult) { r.Family = constant.Raspbian }, false},
		{"pseudo", func(r *models.ScanResult) { r.Family = constant.ServerTypePseudo }, false},
		{"source packages", func(r *models.ScanResult) {
			r.Packages = nil
			r.SrcPackages = models.SrcPackages{"source": {Name: "source"}}
		}, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			r := base
			tt.edit(&r)
			if got := isPkgCvesDetactable(&r); got != tt.want {
				t.Errorf("isPkgCvesDetactable() = %t, want %t", got, tt.want)
			}
		})
	}
}

func TestReuseScannedCvesFromTrivy(t *testing.T) {
	if !reuseScannedCves(&models.ScanResult{ScannedBy: "trivy"}) {
		t.Error("Trivy result should reuse scanned CVEs without Optional")
	}
	if reuseScannedCves(&models.ScanResult{Optional: map[string]interface{}{"trivy-target": "old"}}) {
		t.Error("Optional must not identify a Trivy result")
	}
}

func TestDetectPkgCvesSkipsTrivyWithOSVersion(t *testing.T) {
	r := &models.ScanResult{
		Family: "debian", Release: "12", ScannedBy: "trivy",
		Packages:    models.Packages{"apt": {Name: "apt", Version: "2.0"}},
		ScannedCves: models.VulnInfos{"CVE-2024-0001": {CveID: "CVE-2024-0001"}},
	}
	if err := DetectPkgCves(r, config.GovalDictConf{}, config.GostConf{}, logging.LogOpts{}); err != nil {
		t.Fatal(err)
	}
	if _, ok := r.ScannedCves["CVE-2024-0001"]; !ok {
		t.Error("Trivy CVE was lost")
	}
}

